type GPUOption = {id:string;vram:number;ram?:number;gpu_hourly:number;resource_hourly:number;reservation:number}
type Model = {gpu_options:GPUOption[];id:string; name:string; steps:number; min_steps?:number; max_steps?:number; step_options?:number[]; preparation_ram?:number; variant:string; label:string; gpu:string; vram:number; ram:number; resolution:string; enabled:boolean; image:boolean; audio:boolean; quality:string; source:string; gpu_hourly:number; resource_hourly:number; reservation:number; runtime_hint:string}
type Budget = {id:string;limit:number;confirmed:number;held:number;estimated:number;remaining:number;reconciled_at:string|null;reconciliation_note:string}
type Job = {in_gallery:boolean;render_profile?:string;reconciliation_id:number|null;gpu:string;placement:string;metrics:Record<string,number|string>;id:string;title:string;prompt:string;negative_prompt:string;model_id:string;mode:string;style:string;budget:string;duration:number;aspect:string;seed:number;steps:number;status:string;video_url:string|null;reference_url:string|null;end_reference_url:string|null;reserved_usd:number;estimated_usd:number;billed_usd:number|null;cost_note:string;error:string;elapsed_seconds:number;preparation_seconds:number;created_at:string;finished_at:string|null}
type Bootstrap = {csrf_token:string;models:Model[];budgets:Budget[];paid_enabled:boolean;pricing_date:string;jobs:Job[]}
const money = (n:number, digits=2) => `$${n.toFixed(digits)}`
const elapsed = (seconds:number) => seconds < 60 ? Math.round(seconds) + ' s' : Math.floor(seconds/60) + ' min ' + Math.round(seconds%60) + ' s'
const activeStatuses = ['queued','preparing','running','submitting','submission_unknown','cancelling']
const statusNames:Record<string,string> = {cancelling:'Zaustavljanje…',queued:'Na čekanju',preparing:'Priprema modela na CPU-u',running:'U toku',submitting:'Slanje',submission_unknown:'Provjeri Modal',completed:'Završeno',failed:'Greška',cancelled:'Zaustavljeno'}
const presets = [
  {name:'Mali istraživač',type:'3D animacija',style:'3d',theme:'forest',prompt:'A small friendly orange robot discovers a glowing flower in an enchanted forest at twilight. It tilts its head with curiosity and gently reaches toward the flower. Slow camera push-in, subtle fireflies, one continuous shot, consistent character design.'},
  {name:'Grad iznad oblaka',type:'Anime',style:'anime',theme:'sky',prompt:'A young animated adventurer with a yellow scarf stands on a floating island above soft clouds. A gentle breeze moves the scarf and hair as a tiny airship passes in the distance. Slow cinematic pan, one continuous shot, consistent character design.'},
  {name:'Čarobna šuma',type:'Slikovnica',style:'storybook',theme:'warm',prompt:'A tiny fox wearing a green scarf walks through a magical autumn forest and stops to watch glowing butterflies. Warm painterly storybook animation, gentle natural movement, soft golden light, a single stable shot.'},
  {name:'Vrijeme za kafu',type:'Claymation',style:'clay',theme:'clay',prompt:'A handmade clay bear in a tiny cozy kitchen lifts a little ceramic mug and takes a sip, then smiles. Charming stop-motion animation, tactile clay texture, warm window light, static camera, consistent character design.'},
]

