function App() {
 const [data,setData] = useState<Bootstrap|null>(null)
 const [page,setPage] = useState('studio')
 const [error,setError] = useState('')
 const [notice,setNotice] = useState('')
 const [modelId,setModelId] = useState('wan22-5b')
 const [gpu,setGpu] = useState('L40S')
 const [placement,setPlacement] = useState('resident')
 const [prompt,setPrompt] = useState(presets[0].prompt)
 const [title,setTitle] = useState('Mali istraživač')
 const [style,setStyle] = useState('3d')
 const [duration,setDuration] = useState(5)
 const [renderProfile,setRenderProfile] = useState('standard')
 const [aspect,setAspect] = useState('16:9')
 const [seed,setSeed] = useState(42)
 const [steps,setSteps] = useState(15)
 const [negative,setNegative] = useState('blurry, flickering, distorted anatomy, inconsistent character, text, watermark')
 const [advanced,setAdvanced] = useState(false)
 const [mode,setMode] = useState('demo')
 const [budget,setBudget] = useState('tests')
 const [reference,setReference] = useState<File|null>(null)
 const [referencePreview,setReferencePreview] = useState('')
 const [endReference,setEndReference] = useState<File|null>(null)
 const [endPreview,setEndPreview] = useState('')
 const endUpload = useRef<HTMLInputElement>(null)
 const [busy,setBusy] = useState(false)
 const [selected,setSelected] = useState<Job|null>(null)
 const [theme,setTheme] = useState('forest')
 const [galleryBusy,setGalleryBusy] = useState<string|null>(null)
 const [query,setQuery] = useState('')
 const [filter,setFilter] = useState('all')
 const [reconcile,setReconcile] = useState<Job|null>(null)
 const [invoice,setInvoice] = useState('')
 const [budgetReconcile,setBudgetReconcile] = useState<Budget|null>(null)
 const [budgetAmount,setBudgetAmount] = useState('')
 const [connection,setConnection] = useState<{credentials_present:boolean;paid_enabled:boolean}|null>(null)
 const upload = useRef<HTMLInputElement>(null)
 const model = data?.models.find(m=>m.id===modelId)
 const gpuProfile = model?.gpu_options.find(g=>g.id===gpu)||model?.gpu_options[0]
 const currentBudget = data?.budgets.find(b=>b.id===budget)
 const active = data?.jobs.find(j=>activeStatuses.includes(j.status))
 const reservation = mode==='demo'?0:gpuProfile?.reservation||0
 const totalConfirmed = data?.budgets.reduce((n,b)=>n+b.confirmed,0)||0


 async function api(path:string,options:RequestInit={}) {
  const headers = new Headers(options.headers)
  if (options.method && options.method!=='GET') headers.set('X-CSRFToken',data?.csrf_token||'')
  if (options.body && !(options.body instanceof FormData)) headers.set('Content-Type','application/json')
  const response = await fetch(`/api/${path}`,{...options,headers})
  const result = await response.json().catch(()=>({error:'Server nije vratio ispravan odgovor.'}))
  if (!response.ok) throw new Error(result.error||`Greška ${response.status}`)
  return result
 }
 async function refresh() {
  const response = await fetch('/api/bootstrap/')
  if(!response.ok) throw new Error('Django server nije dostupan.')
  const next:Bootstrap = await response.json(); setData(next)
  setSelected(previous => previous ? next.jobs.find(j=>j.id===previous.id)||previous : next.jobs.find(j=>activeStatuses.includes(j.status))||next.jobs.find(j=>j.mode!=='assembled')||next.jobs[0]||null)
 }
 useEffect(()=>{const close=(e:Event)=>{if(e instanceof KeyboardEvent&&e.key!=='Escape')return;document.querySelectorAll('details.vg-menu[open]').forEach(el=>{if(e instanceof KeyboardEvent||!(e.target instanceof Node)||!el.contains(e.target))el.removeAttribute('open')})};document.addEventListener('pointerdown',close);document.addEventListener('keydown',close);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',close)}},[])
 useEffect(()=>{refresh().catch(e=>setError(e.message))},[])
 useEffect(()=>{
  if(!data) return
  const hasActiveJob=data.jobs.some(j=>activeStatuses.includes(j.status))
  let polling = false
  const timer = window.setInterval(async()=>{
   if(polling) return; polling=true
   try {
    for(const job of data.jobs.filter(j=>activeStatuses.includes(j.status))) await api(`jobs/${job.id}/`)
    await refresh()
   } catch(e) {setError((e as Error).message)} finally {polling=false}
  },hasActiveJob?2500:15000)
  return()=>window.clearInterval(timer)
 },[data?.jobs])
 useEffect(()=>{if(!reference){setReferencePreview('');return}const url=URL.createObjectURL(reference);setReferencePreview(url);return()=>URL.revokeObjectURL(url)},[reference])
 useEffect(()=>{if(!endReference){setEndPreview('');return}const url=URL.createObjectURL(endReference);setEndPreview(url);return()=>URL.revokeObjectURL(url)},[endReference])
 useEffect(()=>{if(!['ltx-2b','ltx23-22b'].includes(modelId))setEndReference(null)},[modelId])
 useEffect(()=>{if(renderProfile!=='standard'&&(modelId!=='ltx23-22b'||!['RTX-PRO-6000','B200'].includes(gpu)||duration!==5||aspect!=='9:16'))setRenderProfile('standard')},[modelId,gpu,duration,aspect])
 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(timer)},[notice])
 useEffect(()=>{if(page==='connection')api('connection/').then(setConnection).catch(e=>setError(e.message))},[page])

 function applyPreset(index:number) {const p=presets[index];setPrompt(p.prompt);setTitle(p.name);setStyle(p.style);setTheme(p.theme);setSelected(null);setPage('studio');setNotice(`Učitan predložak: ${p.name}`)}
 function takeReference(file?:File) {if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){setError('Dodaj PNG, JPEG ili WebP sliku do 8 MB.');return}setReference(file);if(!model?.image){setModelId('wan22-5b');setGpu('L40S');setPlacement('resident');setSteps(15)}setNotice('Početna slika je spremna za animiranje.')}
 function chooseModel(id:string) {
  const next=data?.models.find(m=>m.id===id); if(!next)return
  setModelId(id);setGpu(next.gpu);setRenderProfile('standard')
  setPlacement(id==='ltx23-22b'?'native':id==='hunyuan15-step'?(next.gpu==='L40S'?'offload':'resident'):id==='lightx-wan22'?(next.gpu==='A10'?'merged-blocks':next.gpu==='RTX-PRO-6000'?'merged-resident':'merged'):['wan22-5b','ltx-2b'].includes(id)?'resident':'offload')
  setSteps(id==='wan22-5b'?15:next.steps)
  if(id==='ltx23-22b')setStyle('realistic')
  if(id==='wan21-1.3b')setReference(null)
  if(id!=='ltx23-22b'&&duration>5)setDuration(5);if(['hunyuan15-step','lightx-wan22'].includes(id)&&![3,5].includes(duration))setDuration(5)
 }
 async function generate() {
  setBusy(true);setError('')
  try {
   const form = new FormData()
   Object.entries({title,prompt,model_id:modelId,gpu:gpuProfile?.id,placement,render_profile:renderProfile,style,duration,aspect,seed,steps,negative_prompt:negative,mode,budget}).forEach(([key,value])=>form.append(key,String(value)))
   if(reference)form.append('reference',reference)
   if(endReference&&['ltx-2b','ltx23-22b'].includes(modelId))form.append('end_reference',endReference)
   const job:Job=await api('jobs/',{method:'POST',body:form});setSelected(job);await refresh()
   setNotice(mode==='demo'?'Pokrenut lokalni demo. Modal trošak je 0 $.':'Prvo pripremamo model na CPU-u, zatim pokrećemo jedan GPU.')
  }catch(e){setError((e as Error).message)}finally{setBusy(false)}
 }
 async function cancel(job:Job) {try {await api(`jobs/${job.id}/cancel/`,{method:'POST'});await refresh();setNotice('Posao zaustavljen. Provjeri naplatu za već korištene resurse.')}catch(e){setError((e as Error).message)}}
 async function reuse(job:Job) {if(job.mode==='assembled'){setPage('analysis');setNotice('Obje montirane verzije su u analizi testova.');return}setTitle(job.title);setPrompt(job.prompt);setNegative(job.negative_prompt);setStyle(job.style);setModelId(job.model_id);setGpu(job.gpu==='B200'&&job.model_id!=='ltx23-22b'?'RTX-PRO-6000':job.gpu);setPlacement(job.gpu==='B200'&&job.model_id!=='ltx23-22b'?'resident':job.placement||'offload');setRenderProfile(job.render_profile||'standard');setDuration(job.duration);setAspect(job.aspect);setSeed(job.seed);setSteps(job.steps);setMode(job.mode==='assembled'?'modal':job.mode);setBudget(job.budget);setReference(null);setEndReference(null);setSelected(job);setPage('studio');try {if(job.reference_url){const response=await fetch(job.reference_url);if(!response.ok)throw new Error('Referentna slika nije dostupna.');const blob=await response.blob();setReference(new File([blob],'referentni-lik.png',{type:blob.type}));}if(job.end_reference_url){const response=await fetch(job.end_reference_url);if(!response.ok)throw new Error('Završna slika nije dostupna.');const blob=await response.blob();setEndReference(new File([blob],'end-frame.png',{type:blob.type}));}setNotice('Postavke i referentna slika su učitani.')}catch(e){setError((e as Error).message)}}
 async function reconcileBudget() {if(!budgetReconcile)return;try{await api('billing/reconcile/',{method:'POST',body:JSON.stringify({budget:budgetReconcile.id,amount_usd:budgetAmount,note:'Ručno prepisano iz Modal Usage & Billing pregleda; ukupan iznos za ovaj budžet.'})});setBudgetReconcile(null);await refresh();setNotice('Ukupan iznos je usklađen; stare rezervacije su oslobođene.')}catch(e){setError((e as Error).message)}}
 async function reconcileInvoice() {if(!reconcile)return;try{await api(`jobs/${reconcile.id}/`,{method:'PATCH',body:JSON.stringify({billed_usd:invoice})});setReconcile(null);await refresh();setNotice('Trošak je ručno usklađen.')}catch(e){setError((e as Error).message)}}
 async function toggleGallery(job:Job) {setGalleryBusy(job.id);try{await api(`jobs/${job.id}/`,{method:'PATCH',body:JSON.stringify({in_gallery:!job.in_gallery})});await refresh();setNotice(job.in_gallery?'Video je uklonjen iz galerije. Original ostaje u historiji.':'Video je dodan u galeriju i spreman za Klipanje.')}catch(e){setError((e as Error).message)}finally{setGalleryBusy(null)}}
 const navigation = [{id:'studio',name:'Studio',icon:Clapperboard},{id:'library',name:'Historija',icon:FolderOpen},{id:'models',name:'Modeli i GPU',icon:Cpu},{id:'budget',name:'Budžet',icon:Wallet},{id:'comparison',name:'GPU poređenje',icon:Clock3},{id:'analysis',name:'Analiza testova',icon:FlaskConical},{id:'archive',name:'Sve generacije',icon:Film}]
 const canGenerate = selected?.mode!=='assembled'&&!!data&&!busy&&!active&&(!endReference||!!reference)&&prompt.trim().length>=10&&(currentBudget?.remaining||0)>=reservation&&(mode==='demo'||data.paid_enabled)
 const measuredJobs = data?.jobs.filter(j=>j.mode==='modal'&&j.status==='completed'&&Number(j.metrics?.load_seconds)>0)||[]
 const preparationCost = (job:Job) => {const m=data?.models.find(m=>m.id===job.model_id);return (2*.0000131+(m?.preparation_ram||8)*.00000222)*job.preparation_seconds}
 const totalWait = (job:Job) => job.finished_at?Math.max(0,(Date.parse(job.finished_at)-Date.parse(job.created_at))/1000):0
 const measuredCost = (job:Job) => {const m=data?.models.find(m=>m.id===job.model_id);const g=m?.gpu_options.find(g=>g.id===job.gpu);return (g?.resource_hourly||0)/3600*job.elapsed_seconds+preparationCost(job)+Math.max(0,Number(job.metrics.peak_cpu_ram_gib||0)-(g?.ram??m?.ram??0))*.00000222*job.elapsed_seconds}
 const pageTitle = page==='archive'?'Sve generacije':page==='analysis'?'Analiza testova':page==='comparison'?'GPU poređenje':page==='studio'?'Kreiraj scenu':page==='gallery'?'Galerija':page==='library'?'Historija generisanja':page==='models'?'Modeli i GPU':page==='budget'?'Budžet i potrošnja':'Modal povezivanje'

 return <div className="app-shell">
  <header className="vg-header">
   <a className="vg-brand" href="#" onClick={e=>{e.preventDefault();setPage('studio')}}><LogoMark size={34}/>VideoGen</a>
   <nav aria-label="Glavna navigacija">{[{id:'studio',name:'Generisanje'},{id:'gallery',name:'Galerija'},{id:'library',name:'Historija'}].map(item=><button key={item.id} aria-current={page===item.id?'page':undefined} className={page===item.id?'active':''} onClick={()=>{setPage(item.id);setQuery('');setFilter('all')}}>{item.name}{item.id==='gallery'&&<span>{data?.jobs.filter(j=>j.in_gallery).length||0}</span>}</button>)}</nav>
   <div className="vg-header-actions"><details className="vg-menu"><summary>Alati <ChevronDown size={14}/></summary><div>{navigation.filter(item=>!['studio','library'].includes(item.id)).map(item=><button key={item.id} onClick={()=>{setPage(item.id);document.querySelectorAll('details.vg-menu').forEach(el=>el.removeAttribute('open'))}}><item.icon size={16}/>{item.name}</button>)}<button onClick={()=>setPage('connection')}><Link2 size={16}/>Modal povezivanje</button></div></details><details className="vg-menu vg-themes"><summary>Teme <ChevronDown size={14}/></summary><ThemePicker/></details><a className="vg-return" href="http://127.0.0.1:5175/">← Klipanje</a></div>
  </header>
  <div className="main-shell">
   <main>
    <div className="page-heading"><div><div className="eyebrow"><span/> KLIPANJE · VIDEO STUDIO</div><h1>{page==='studio'?<>Generiši <em>video.</em></>:pageTitle}</h1><p>{page==='studio'?'Daj život svojim likovima, jednu scenu po jednu.':page==='gallery'?'Odabrani videi za tvoje projekte u Klipanju.':page==='library'?'Svi pokušaji, postavke i rezultati. Završene videe dodaj u galeriju.':page==='models'?'Počni malim modelom. Mjeri cijenu, pa podigni kvalitet.':page==='budget'?'Dva odvojena budžeta. Svaki dolar ima svoju svrhu.':page==='comparison'?'Brzina je korisna kada smanjuje i cijenu korisnog rezultata.':page==='archive'?'Svi pokušaji od početka, od najjeftinijih prema skupljima.':page==='analysis'?'Rezultati, troškovi i odluke iz dosadašnjih proba.':'Lokalni studio, računar u oblaku kad ti zatreba.'}</p></div><span className="version"><Monitor size={14}/> Lokalni studio</span></div>
    {error&&<div className="alert error" role="alert"><span>{error}</span><button onClick={()=>setError('')} aria-label="Zatvori grešku"><X size={16}/></button></div>}
    {!data?<div className="loading"><LoaderCircle className="spin"/>Povezivanje s lokalnim studiom…<button className="button secondary" onClick={()=>refresh().catch(e=>setError(e.message))}>Pokušaj ponovo</button></div>:<>
    {page==='studio'&&<>
     <div className="vg-workflow"><span className="active"><b>1</b> Generiši video</span><ChevronRight size={15}/><button onClick={()=>setPage('library')}><b>2</b> Odaberi rezultat</button><ChevronRight size={15}/><button onClick={()=>setPage('gallery')}><b>3</b> Galerija i Klipanje</button></div>
     <div className="studio-toolbar"><div className="segment"><button className={mode==='demo'?'selected':''} onClick={()=>setMode('demo')}><Monitor size={14}/>Lokalni demo<span className="free-badge">$0</span></button><button className={mode==='modal'?'selected':''} onClick={()=>{if(data.paid_enabled)setMode('modal');else {setPage('connection');setNotice('Prvo poveži Modal. Lokalni demo je spreman.')}}}><Zap size={14}/>Modal GPU{!data.paid_enabled&&<span className="muted-dot"/>}</button></div><span className="toolbar-note">{mode==='demo'?<><span className="tiny-dot"/>Bez potrošnje kredita</>:<><Cpu size={14}/>1 × {gpuProfile?.id}</>}</span></div>
     <div className="studio-grid">
      <section className="panel composer"><div className="panel-heading"><div><span className="step-number">01</span><h2>Tvoja scena</h2></div><Sparkles size={17}/></div>
       <div className="composer-inner"><div className="field-label"><label htmlFor="scene-title">NAZIV SCENE</label><span>Samo za tvoju organizaciju</span></div><input id="scene-title" value={title} onChange={e=>setTitle(e.target.value)} maxLength={120} className="title-input" placeholder="Daj sceni ime"/>
        <div className="field-label"><label htmlFor="prompt">OPIS SCENE</label><button className="text-button" onClick={()=>applyPreset((presets.findIndex(p=>p.prompt===prompt)+1)%presets.length)}><WandSparkles size={12}/>Isprobaj ideju</button></div>
        <div className="prompt-field"><textarea id="prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} maxLength={4000} placeholder="Ko je u sceni? Šta radi? Kako se kamera kreće?"/><div><span>Lik + radnja + okruženje + kamera</span><span>{prompt.length}/4000</span></div></div>
        <p className="field-hint">Za početak: jedan lik, jedna radnja i mirna kamera. Engleski opis je dobar početni izbor.</p>
        <div className="field-label"><span>POČETNA SLIKA</span><span>Opcionalno · za isti izgled lika</span></div>
        <input type="file" ref={upload} accept="image/png,image/jpeg,image/webp" hidden onChange={e=>takeReference(e.target.files?.[0])}/>
        <div className={`upload-zone ${reference?'has-image':''}`} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();takeReference(e.dataTransfer.files[0])}}>{reference?<><img src={referencePreview} alt="Referentni lik"/><div><strong>{reference.name}</strong><small>{model?.name} · image-to-video</small></div><button className="icon-button" aria-label="Ukloni sliku" onClick={()=>{setReference(null);if(upload.current)upload.current.value=''}}><X size={15}/></button></>:<button onClick={()=>upload.current?.click()}><span className="upload-icon"><ImagePlus size={20}/></span><div><strong>Dodaj svog lika ili početni kadar</strong><small>Prevuci sliku ili <u>izaberi datoteku</u> · do 8 MB</small></div><Plus size={17}/></button>}</div>
        {['ltx-2b','ltx23-22b'].includes(modelId)&&<><div className="field-label"><span>ZAVRŠNA SLIKA</span><span>Opcionalno · zadaj krajnju pozu</span></div><input type="file" ref={endUpload} accept="image/png,image/jpeg,image/webp" hidden onChange={e=>{const f=e.target.files?.[0];if(f&&['image/png','image/jpeg','image/webp'].includes(f.type)&&f.size<=8*1024*1024)setEndReference(f);else if(f)setError('Dodaj PNG, JPEG ili WebP sliku do 8 MB.')}}/><div className={`upload-zone ${endReference?'has-image':''}`}>{endReference?<><img src={endPreview} alt="Završni kadar"/><div><strong>{endReference.name}</strong><small>Pokret između početne i završne slike</small></div><button className="icon-button" aria-label="Ukloni završnu sliku" onClick={()=>{setEndReference(null);if(endUpload.current)endUpload.current.value=''}}><X size={15}/></button></>:<button onClick={()=>endUpload.current?.click()}><span className="upload-icon"><ImagePlus size={20}/></span><div><strong>Dodaj završnu sliku</strong><small>Isti likovi i kadar daju bolju vezu · do 8 MB</small></div><Plus size={17}/></button>}</div></>}
        <div className="field-label style-label"><span>VIZUALNI STIL</span></div><div className="style-options">{[{id:'3d',name:'3D animacija',icon:'◈'},{id:'anime',name:'Anime',icon:'✧'},{id:'storybook',name:'Slikovnica',icon:'❋'},{id:'clay',name:'Claymation',icon:'●'},{id:'realistic',name:'Realistično',icon:'◉'}].map(s=><button key={s.id} onClick={()=>setStyle(s.id)} className={style===s.id?'chosen':''}><span>{s.icon}</span>{s.name}{style===s.id&&<Check size={12}/>}</button>)}</div>
        {selected?.mode==='assembled'&&<p className="field-hint">Spojeni video koristi dva izvorna AI dijela. Za novu generaciju učitaj jedan od izvornih dijelova iz biblioteke.</p>}<div className="settings-row"><label>MODEL<select value={modelId} onChange={e=>chooseModel(e.target.value)}>{data.models.filter(m=>m.enabled).map(m=><option key={m.id} value={m.id}>{m.name} · {m.variant.split(' · ')[0]}</option>)}</select></label><label>TRAJANJE<select value={duration} onChange={e=>setDuration(Number(e.target.value))}>{(modelId==='ltx23-22b'?[3,5,10]:['hunyuan15-step','lightx-wan22'].includes(modelId)?[3,5]:[2,3,4,5]).map(n=><option key={n} value={n}>{n} sekundi</option>)}</select></label><label>FORMAT<select value={aspect} onChange={e=>setAspect(e.target.value)}><option>16:9</option><option>9:16</option><option>1:1</option></select></label></div>
        <div className="settings-row gpu-settings"><label>GPU<select value={gpuProfile?.id||''} onChange={e=>{setGpu(e.target.value);if(modelId==='lightx-wan22')setPlacement(e.target.value==='A10'?'merged-blocks':e.target.value==='RTX-PRO-6000'?'merged-resident':'merged');else if(modelId==='hunyuan15-step'){setPlacement(e.target.value==='A10'?'merged-blocks':e.target.value==='L40S'?'offload':'resident');if(['L40S','A10','B200'].includes(e.target.value))setSteps(8)}else if(modelId==='ltx23-22b')setPlacement('native');else if(!['L40S','A100-80GB','RTX-PRO-6000','B200'].includes(e.target.value))setPlacement('offload')}}>{model?.gpu_options.map(g=><option key={g.id} value={g.id}>{g.id} · {g.vram} GB</option>)}</select></label><div className="gpu-rate"><span>GPU + CPU + RAM</span><strong>~{money(gpuProfile?.resource_hourly||0)} / sat</strong><small>Trošak zavisi od vremena rada.</small></div></div>
        <button className="advanced-toggle" onClick={()=>setAdvanced(!advanced)} aria-expanded={advanced}><Settings2 size={14}/>Napredne postavke<ChevronDown size={14} className={advanced?'rotate':''}/></button>
        {advanced&&<div className="advanced-fields">{modelId==='ltx23-22b'&&<label>DETALJI SLIKE<select value={renderProfile} onChange={e=>setRenderProfile(e.target.value)}><option value="standard">Standard · 576 × 1024 u portretu</option><option value="detail" disabled={!['RTX-PRO-6000','B200'].includes(gpu)||duration!==5||aspect!=='9:16'}>Više detalja · 864 × 1536 · 5 s · RTX/B200</option><option value="ultra" disabled={!['RTX-PRO-6000','B200'].includes(gpu)||duration!==5||aspect!=='9:16'}>Najviše detalja · 1152 × 2048 · 5 s · RTX/B200</option></select></label>}<div className="settings-row"><label>SEED<input type="number" min="0" max="2147483647" value={seed} onChange={e=>setSeed(Number(e.target.value))}/></label><label>KORACI<input type="number" min={model?.min_steps??(modelId==='ltx-2b'?8:10)} max={modelId==='hunyuan15-step'&&['L40S','A10','B200'].includes(gpuProfile?.id||'')?8:(model?.max_steps??(modelId==='ltx-2b'?8:50))} value={steps} onChange={e=>setSteps(Number(e.target.value))}/></label><label>BUDŽET<select value={budget} onChange={e=>setBudget(e.target.value)}><option value="tests">Testiranje</option><option value="creative">Moje scene</option></select></label></div>{['wan22-5b','ltx-2b'].includes(modelId)&&['L40S','A100-80GB','RTX-PRO-6000','B200'].includes(gpuProfile?.id||'')&&<label className="negative-label">MEMORIJSKI PROFIL<select className="placement-select" value={placement} onChange={e=>setPlacement(e.target.value)}><option value="offload">Standard · premještanje CPU / GPU</option><option value="resident">Sve u GPU memoriji</option></select></label>}{modelId==='lightx-wan22'&&<label className="negative-label">UČITAVANJE MODELA<select className="placement-select" value={placement} onChange={e=>setPlacement(e.target.value)}>{gpuProfile?.id==='L40S'&&<option value="offload">Početni testni profil</option>}{gpuProfile?.id==='A10'?<option value="merged-blocks">Pripremljen model · manji dijelovi u GPU-u</option>:<option value={gpuProfile?.id==='RTX-PRO-6000'?'merged-resident':'merged'}>{gpuProfile?.id==='RTX-PRO-6000'?'Pripremljen model · sve u GPU memoriji':'Pripremljen model · kraće učitavanje'}</option>}</select></label>}<label className="negative-label">ŠTA IZBJEĆI<textarea value={negative} onChange={e=>setNegative(e.target.value)} maxLength={2000}/></label><p className="field-hint">Isti seed olakšava poređenje. Broj koraka utiče na doradu i vrijeme, ne određuje količinu pokreta. LTX Distilled koristi propisani raspored od 8 koraka; na guidance 1 negativni opis se ne primjenjuje. Hunyuan koristi 8 ili 12, a LightX2V profil 4 koraka; i oni rade bez negativnog opisa. LTX-2.3 koristi 8 osnovnih + 3 koraka dorade, također bez negativnog opisa.</p></div>}
       </div>
       <div className="generate-footer"><div className="estimate-row"><div><span className="cost-icon"><Wallet size={16}/></span><div><span>{mode==='demo'?'Trošak ovog demo testa':'Rezervacija budžeta'}</span><strong>{money(reservation,mode==='demo'?2:3)}<small> / pokušaj</small></strong></div></div><span className="budget-chip">{budget==='tests'?'Testiranje':'Moje scene'}<b>{money(currentBudget?.remaining||0)}</b></span></div><button className="button primary generate" disabled={!canGenerate} onClick={generate}>{busy||active?<LoaderCircle size={18} className="spin"/>:<Sparkles size={18}/>} {busy?'Pokretanje…':active?'Scena se priprema…':mode==='demo'?'Isprobaj lokalni demo':'Generiši scenu'}{!busy&&!active&&<ArrowRight size={18}/>}</button><p className="footer-note"><ShieldCheck size={12}/>{mode==='demo'?'Tehnička animacija za provjeru aplikacije. Nije AI generisanje.':'Rezervacija nije račun. Pohrana se obračunava odvojeno.'}</p></div>
      </section>
      <div className="right-column"><section className="panel preview-panel"><div className="panel-heading"><div><span className="step-number">02</span><h2>Pregled scene</h2></div><span className="preview-badge">{selected?.mode==='modal'?(selected.video_url?'AI REZULTAT':'AI POSAO · MODAL'):selected?'LOKALNI DEMO':'VIZUALNI PRIMJER'}</span></div><div className={`preview-canvas ${selected?.aspect==='9:16'?'portrait':''}`}>{selected?.video_url?<video key={selected.video_url} src={selected.video_url} controls playsInline loop/>:selected?.reference_url?<img className="reference-canvas" src={selected.reference_url} alt="Početna slika — ovo još nije AI rezultat"/>:<SceneArt theme={theme}/>}<span className="canvas-corner">{selected?.video_url?'VIDEOGEN OUTPUT':selected?.reference_url?'POČETNA SLIKA':'ANIMATION PLAYGROUND'}</span>{active&&selected?.id===active.id&&<div className="render-overlay"><LoaderCircle size={29} className="spin"/><strong>{active.mode==='demo'?'Pripremam demo animaciju':active.status==='preparing'?'Pripremam model na CPU-u':'Dodjela kartice ili GPU obrada'}</strong><span>{active.status==='submission_unknown'?'Provjeri slanje u Modal dashboardu.':'Na slobodnu karticu čekamo najviše 10 min.'}</span><button onClick={()=>cancel(active)}>Zaustavi posao</button></div>}</div>
       <div className="preview-caption"><div><span className={`tiny-dot ${selected?.status==='failed'?'red':''}`}/><strong>{selected?statusNames[selected.status]:'Prostor za tvoju sljedeću priču'}</strong><small>{selected?`${selected.duration}s · ${selected.aspect} · ${selected.mode==='demo'?'lokalni demo':data.models.find(m=>m.id===selected.model_id)?.name}`:'Ilustracija · nije rezultat AI modela'}</small></div>{selected?.video_url?<a href={selected.video_url} download className="icon-button" aria-label="Preuzmi video"><ArrowDownToLine size={17}/></a>:<Aperture size={21}/>}</div>{selected?.video_url&&selected.status==='completed'&&<div className="vg-preview-actions"><button className="button secondary" disabled={galleryBusy===selected.id} onClick={()=>void toggleGallery(selected)}>{selected.in_gallery?<Check size={15}/>:<Plus size={15}/>} {galleryBusy===selected.id?'Spremam…':selected.in_gallery?'Ukloni iz galerije':'Dodaj u galeriju'}</button><button className="text-button" onClick={()=>{setPage('gallery');setQuery('');setFilter('all')}}>Otvori galeriju <ArrowRight size={14}/></button></div>}{selected?.error&&<div className="job-error">{selected.error}</div>}
      </section><section className="gpu-summary"><span className="gpu-icon"><Cpu size={21}/></span><div><strong>{mode==='demo'?'Tvoj računar je dovoljan':`1 × NVIDIA ${gpuProfile?.id}`}</strong><p>{mode==='demo'?'Interfejs i demo rade lokalno. GPU u oblaku se ne pokreće.':`${gpuProfile?.vram} GB VRAM · ${modelId==='ltx23-22b'?(renderProfile==='ultra'?'1152 × 2048':renderProfile==='detail'?'864 × 1536':({'9:16':'576 × 1024','16:9':'1024 × 576','1:1':'768 × 768'}[aspect])):model?.resolution} · bez stalno upaljenog GPU-a`}</p></div><span className="eco-tag"><Sprout size={12}/>Štedljiv početak</span></section><div className="tip-card"><span>✦</span><div><strong>Dosljedan lik počinje dobrom slikom.</strong><p>Za svoje animirane likove koristi početni kadar i opiši samo pokret. Wan 2.2 i LTX 2B podržavaju početnu sliku.</p></div><ArrowRight size={17}/></div></div>
     </div>
     <section className="ideas-section"><div className="section-heading"><div><h2>Malo inspiracije za prvi kadar</h2><span>Izaberi ideju, pa je pretvori u svoju.</span></div><span className="subtle-label">4 STARTER SCENE</span></div><div className="ideas-grid">{presets.map((preset,i)=><button className="idea-card" key={preset.name} onClick={()=>applyPreset(i)}><div className={`idea-art art-${preset.theme}`}><SceneArt theme={preset.theme} id={`idea-${i}`}/><span><ArrowRight size={16}/></span></div><div className="idea-info"><strong>{preset.name}</strong><span>{preset.type}</span></div></button>)}</div></section>
    </>}
    {(page==='library'||page==='gallery')&&<>{page==='gallery'&&<div className="vg-gallery-info"><FolderOpen size={24}/><div><strong>Iz galerije u Klipanje</strong><p>Klikni Prebaci u Klipanje, odaberi projekat i skriptu pa potvrdi spremanje. Video će biti u Mediji → Video u editoru te skripte.</p></div><a href="http://127.0.0.1:5175/videa">Otvori Klipanje <ExternalLink size={14}/></a></div>}<div className="library-toolbar"><div className="segment">{(page==='gallery'?[['all','Svi videi'],['modal','AI videi'],['demo','Demo']]:[['all','Sve scene'],['completed','Završene'],['modal','Modal'],['demo','Demo']]).map(([id,label])=><button className={filter===id?'selected':''} onClick={()=>setFilter(id)} key={id}>{label}</button>)}</div><input className="vg-search" aria-label="Pretraži videe" placeholder="Pretraži po nazivu ili promptu…" value={query} onChange={e=>setQuery(e.target.value)}/><button className="button primary" onClick={()=>{setSelected(null);setPage('studio')}}><Plus size={15}/>Nova scena</button></div>{data.jobs.filter(j=>(page!=='gallery'||j.in_gallery)&&(filter==='all'||j.status===filter||j.mode===filter||(filter==='modal'&&j.mode==='assembled'))&&(!query.trim()||`${j.title} ${j.prompt}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()))).length===0?<EmptyState icon={<Film size={32}/>} title={page==='gallery'?'Galerija čeka tvoje odabrane videe.':'Nema scena za ovaj prikaz.'} text={page==='gallery'?'U historiji izaberi završeni video i klikni Dodaj u galeriju.':'Promijeni pretragu ili započni novu scenu.'} action={()=>{setPage(page==='gallery'?'library':'studio');setQuery('');setFilter('all')}} actionText={page==='gallery'?'Otvori historiju':'Nova scena'}/>:<div className="jobs-grid">{data.jobs.filter(j=>(page!=='gallery'||j.in_gallery)&&(filter==='all'||j.status===filter||j.mode===filter||(filter==='modal'&&j.mode==='assembled'))&&(!query.trim()||`${j.title} ${j.prompt}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()))).map(job=><article className="panel job-card" key={job.id}><div className="job-media">{job.video_url?<video src={job.video_url} controls preload="metadata"/>:<>{job.reference_url?<img src={job.reference_url} alt="Početni kadar"/>:<SceneArt id={job.id}/>}<span>{statusNames[job.status]}</span></>}</div><div className="job-card-body"><div className="job-title"><h3>{job.title}</h3><span className={`status ${job.status}`}>{statusNames[job.status]}</span></div><p>{job.prompt}</p><div className="job-meta"><span>{data.models.find(m=>m.id===job.model_id)?.name} · {job.duration}s · {job.gpu}</span><span>{job.mode==='assembled'?'Spojeno · trošak je u izvorima':job.mode==='demo'?'DEMO · $0':job.reconciliation_id?'Usklađeno u ukupnom iznosu':job.billed_usd!==null?`${money(job.billed_usd,3)} uneseno`:job.status==='completed'&&job.elapsed_seconds>0?`~${money(job.estimated_usd,3)} procjena`:`${money(job.reserved_usd,3)} rezervisano`}</span></div><div className="job-timing"><Clock3 size={12}/><span>{job.mode==='assembled'?'Spojeno lokalno · bez nove GPU generacije':job.preparation_seconds ? 'CPU priprema: ' + elapsed(job.preparation_seconds) + ' · ' : ''}{job.mode==='assembled'?'':job.elapsed_seconds ? (job.mode === 'demo' ? 'Lokalno: ' : 'GPU posao: ') + elapsed(job.elapsed_seconds) : 'Vrijeme će se zabilježiti po završetku.'}</span></div>{job.mode==='modal'&&Number(job.metrics?.load_seconds)>0&&<div className="job-metrics"><span>Učitavanje <b>{elapsed(Number(job.metrics.load_seconds))}</b></span><span>Model + ulaz <b>{elapsed(Number(job.metrics.sampling_and_conditioning_seconds||0))}</b></span><span>Dekodiranje <b>{elapsed(Number(job.metrics.decode_seconds||0))}</b></span><span>Vrh VRAM-a <b>{Number(job.metrics.peak_allocated_vram_gib||0).toFixed(1)} GiB</b></span>{Number(job.metrics.peak_cpu_ram_gib)>0&&<span>RAM na Modalu <b>{Number(job.metrics.peak_cpu_ram_gib).toFixed(1)} GiB</b></span>}<span>Profil <b>{job.placement==='native'?'GPU po fazama (native)':['resident','merged-resident'].includes(job.placement)?'Sve na GPU-u':job.placement==='merged-blocks'?'CPU / GPU po blokovima':'CPU / GPU'}</b></span></div>}<div className="job-actions">{job.video_url&&job.status==='completed'&&<button disabled={galleryBusy===job.id} className="gallery-action" onClick={()=>void toggleGallery(job)}>{job.in_gallery?<Check size={14}/>:<Plus size={14}/>} {galleryBusy===job.id?'Spremam…':job.in_gallery?'Ukloni iz galerije':'Dodaj u galeriju'}</button>}{job.video_url&&job.in_gallery&&<button onClick={()=>{setNotice('Otvoreno je Klipanje. Tamo odaberi projekat i skriptu.');void transferToKlipanje(job).then(()=>setNotice('Video je primljen u Klipanje. Potvrdi projekat i skriptu za spremanje.')).catch(e=>setError(e.message));}}><ArrowRight size={13}/>Prebaci u Klipanje</button>}<button onClick={()=>reuse(job)}><RefreshCw size={13}/>{job.mode==='assembled'?'Pogledaj spojeni video':'Učitaj postavke'}</button>{activeStatuses.includes(job.status)?<button onClick={()=>cancel(job)}><X size={13}/>Zaustavi</button>:job.mode==='modal'&&!job.reconciliation_id?<button onClick={()=>{setReconcile(job);setInvoice(String(job.billed_usd??''))}}><Wallet size={13}/>Uskladi račun</button>:job.video_url&&<a href={job.video_url} download><ArrowDownToLine size={13}/>Preuzmi</a>}</div>{job.metrics.review&&<p className="field-hint"><strong>Pregled rezultata:</strong> {String(job.metrics.review)}</p>}{job.error&&<p className="job-error">{job.error}</p>}</div></article>)}</div>}</>}
    {page==='models'&&<><div className="info-banner"><Sprout size={20}/><div><strong>Jeftiniji GPU po satu nije uvijek jeftiniji video.</strong><p>Prvo mjerimo ukupno vrijeme i kvalitet. Svi profili koriste jedan GPU. Stvarna mjerenja su na stranici GPU poređenje.</p></div></div><div className="models-grid">{data.models.map((m,i)=><article className={`panel model-card ${i===0?'recommended':''}`} key={m.id}><div className="model-top"><span className="model-monogram">{m.id==='h3'?'M':m.id==='hunyuan15-step'?'H':m.id==='ltx-2b'?'L':'W'}<small>{i+1}</small></span><span className={m.enabled?'model-ready':'model-planned'}>{m.enabled?'Worker pripremljen':'Planirana integracija'}</span></div><h2>{m.name}</h2><span className="model-variant">{m.variant}</span><p>{m.quality}</p><dl><div><dt>Jedan GPU</dt><dd>{m.gpu} · {m.vram} GB</dd></div><div><dt>Rezolucija</dt><dd>{m.resolution}</dd></div><div><dt>GPU / sat</dt><dd>{money(m.gpu_hourly)}</dd></div><div><dt>GPU + CPU + RAM / sat</dt><dd>~{money(m.resource_hourly)}</dd></div><div><dt>Početna slika / zvuk</dt><dd>{m.image?'Da':'Ne'} / {m.audio?'Da':'Ne'}</dd></div></dl><p className="model-note">{m.runtime_hint}</p><div className="model-card-footer"><a href={m.source} target="_blank" rel="noreferrer">Službeni model<ExternalLink size={13}/></a><button disabled={!m.enabled} onClick={()=>{chooseModel(m.id);setPage('studio')}}>{m.enabled?'Izaberi model':'Uskoro'}<ArrowRight size={14}/></button></div></article>)}</div><p className="source-note">Cijene provjerene {data.pricing_date}. Pohrana i mreža nisu uključene. <a href="https://modal.com/pricing" target="_blank" rel="noreferrer">Modal cjenovnik ↗</a></p></>}
    {page==='archive'&&<GenerationArchive/>}
    {page==='analysis'&&<ExperimentAnalysis/>}
    {page==='comparison'&&<><div className="info-banner"><Clock3 size={20}/><div><strong>Poredi isti kadar i iste postavke.</strong><p>Za pošteno poređenje koristi istu sliku, prompt, seed, rezoluciju, trajanje i broj koraka. Svaki red je jedno mjerenje; model i sadržaj također utiču na brzinu.</p></div></div><section className="panel ledger"><div className="panel-heading"><h2>Izmjerena vremena i cijena resursa</h2><span>{measuredJobs.length} mjerenja</span></div>{measuredJobs.length===0?<div className="ledger-empty">Prvi uporedivi testovi su u toku. Rezultati se pojavljuju po završetku.</div>:<div className="table-wrap"><table className="comparison-table"><thead><tr><th>GPU / SCENA</th><th>POSTAVKE</th><th>UKUPNO GPU POSAO</th><th>PROCJENA RESURSA</th><th>UČITAVANJE</th><th>MODEL + ULAZ</th><th>DEKODIRANJE</th></tr></thead><tbody>{measuredJobs.map(j=><tr key={j.id}><td><strong>{j.gpu}</strong><small>{data.models.find(m=>m.id===j.model_id)?.name} · {data.models.find(m=>m.id===j.model_id)?.variant}</small><small>{String(j.metrics.gpu_name||'')}</small><small>{j.placement==='native'?'GPU po fazama (native)':['resident','merged-resident'].includes(j.placement)?'Sve u VRAM-u':j.placement==='merged-blocks'?'CPU / GPU po blokovima':'CPU / GPU'}</small><small>{j.title}</small></td><td>{j.duration}s · {j.aspect}<small>{j.steps} koraka · seed {j.seed}</small>{Number(j.metrics.output_width)>0&&<small>{String(j.metrics.output_width)} × {String(j.metrics.output_height)}</small>}<small>VRAM {Number(j.metrics.peak_allocated_vram_gib||0).toFixed(1)} GiB</small></td><td>{elapsed(j.elapsed_seconds)}<small>Od slanja: {elapsed(totalWait(j))}</small></td><td>~{money(measuredCost(j),3)}<small>GPU posao: {money(measuredCost(j)-preparationCost(j),3)}</small><small>CPU priprema: {money(preparationCost(j),3)}</small>{Number(j.metrics.peak_cpu_ram_gib)>(data.models.find(m=>m.id===j.model_id)?.gpu_options.find(g=>g.id===j.gpu)?.ram??data.models.find(m=>m.id===j.model_id)?.ram??Infinity)&&<small>Gornja procjena zbog vrha RAM-a</small>}</td><td>{elapsed(Number(j.metrics.load_seconds||0))}</td><td>{elapsed(Number(j.metrics.sampling_and_conditioning_seconds||0))}</td><td>{elapsed(Number(j.metrics.decode_seconds||0))}</td></tr>)}</tbody></table></div>}</section><p className="source-note">Procjena koristi izmjerena vremena unutar funkcija i javne cijene GPU-a, CPU-a i RAM-a. Pokretanje kontejnera i pohrana mogu dodati trošak. Ovo nije Modal račun.</p></>}
    {page==='budget'&&<><div className="budget-overview"><div><span className="eyebrow">USKLAĐENA POTROŠNJA</span><strong>{money(totalConfirmed)}</strong><p>od ukupno $30.00 za ovaj eksperiment</p></div><ShieldCheck size={48}/></div><div className="budget-grid">{data.budgets.map(b=><section className="panel budget-panel" key={b.id}><div className="panel-heading"><div>{b.id==='tests'?<FlaskConical size={19}/>:<Clapperboard size={19}/>}<h2>{b.id==='tests'?'Tehnički testovi':'Tvoje kreativne scene'}</h2></div><span>$15.00 limit</span></div><div className="budget-remaining"><strong>{money(b.remaining)}</strong><span>slobodno za sljedeći pokušaj</span></div><div className="budget-bar"><i style={{width:`${Math.min(100,b.confirmed/b.limit*100)}%`}}/><i className="held" style={{width:`${Math.min(100,b.held/b.limit*100)}%`}}/><i className="estimated" style={{width:`${Math.min(100,(b.estimated||0)/b.limit*100)}%`}}/></div><dl><div><dt><span className="tiny-dot"/>Ručno usklađeno</dt><dd>{money(b.confirmed,3)}</dd></div><div><dt><span className="tiny-dot amber"/>Aktivno / nerazjašnjeno</dt><dd>{money(b.held,3)}</dd></div><div><dt>Procjene novih završenih poslova</dt><dd>~{money(b.estimated||0,3)}</dd></div></dl><div className="budget-reconcile"><button className="button secondary" disabled={!!active} onClick={()=>{setBudgetReconcile(b);setBudgetAmount(String(b.confirmed||''))}}>Uskladi ukupan iznos</button>{b.reconciled_at&&<small>Posljednje usklađivanje: {new Date(b.reconciled_at).toLocaleString('bs-BA')}</small>}</div></section>)}</div><div className="info-banner"><ShieldCheck size={20}/><div><strong>Budžet aplikacije i Modal račun su odvojene stvari.</strong><p>Uspješno završeni poslovi oslobađaju veliku rezervaciju i privremeno se računaju po procjeni. Greške i nepoznati ishodi čuvaju rezervaciju. Ukupno usklađivanje zamjenjuje stare iznose jednim iznosom s Modala, bez izmišljanja pojedinačnih računa. Modal limit od $15 ostaje zasebna zaštita.</p><a href="https://modal.com/settings" target="_blank" rel="noreferrer">Otvori Modal postavke <ExternalLink size={13}/></a></div></div><section className="panel ledger"><div className="panel-heading"><h2>Evidencija pokušaja</h2><span>{data.jobs.filter(j=>j.mode==='modal').length} Modal pokušaja</span></div>{data.jobs.filter(j=>j.mode==='modal').length===0?<div className="ledger-empty">Još nema plaćenih pokušaja. Lokalni demo ne troši kredit.</div>:<div className="table-wrap"><table><thead><tr><th>SCENA</th><th>BUDŽET</th><th>POČETNA REZERVA</th><th>RANIJA PRIVREMENA PROCJENA</th><th>RUČNI RAČUN</th><th/></tr></thead><tbody>{data.jobs.filter(j=>j.mode==='modal').map(j=><tr key={j.id}><td>{j.title}<small>{statusNames[j.status]}</small></td><td>{j.budget==='tests'?'Testiranje':'Moje scene'}</td><td>{money(j.reserved_usd,3)}</td><td>{j.elapsed_seconds?money(j.estimated_usd,3):'—'}</td><td>{j.reconciliation_id?'Obuhvaćeno ukupnim iznosom':j.billed_usd===null?'Čeka usklađivanje':money(j.billed_usd,3)}</td><td><button disabled={activeStatuses.includes(j.status)||!!j.reconciliation_id} onClick={()=>{setReconcile(j);setInvoice(String(j.billed_usd??''))}} className="text-button">Uskladi</button></td></tr>)}</tbody></table></div>}</section></>}
    {page==='connection'&&<div className="connection-layout"><section className="panel connect-panel"><div className="connect-logo"><Link2 size={28}/></div><span className="eyebrow">CLOUD GPU CONNECTION</span><h2>Tvoj studio + Modal.</h2><p>Lokalni dio je spreman. GPU se pokreće samo za poslani posao.</p><div className="connection-checks"><div><Check size={17}/><span>React + Django rade lokalno</span><strong>Spremno</strong></div><div>{connection?.credentials_present?<Check size={17}/>:<Clock3 size={17}/>}<span>Modal prijava na računaru</span><strong>{connection?.credentials_present?'Prisutna':'Nije pronađena'}</strong></div><div>{data.paid_enabled?<Check size={17}/>:<Clock3 size={17}/>}<span>Slanje plaćenih poslova</span><strong>{data.paid_enabled?'Uključeno':'Isključeno'}</strong></div></div><a href="https://modal.com/apps" target="_blank" rel="noreferrer" className="button primary">Otvori Modal<ExternalLink size={15}/></a><button className="button secondary" onClick={()=>{api('connection/').then(setConnection).catch(e=>setError(e.message));refresh().catch(e=>setError(e.message))}}><RefreshCw size={14}/>Osvježi status</button><p className="field-hint">Prisustvo prijave nije potvrda objavljenog workera. Deployment se provjerava prije slanja posla.</p></section><div><section className="panel setup-guide"><div className="panel-heading"><h2>Kako je sve povezano</h2><Cpu size={17}/></div><ol><li><span>01</span><div><strong>Lokalni studio</strong><p>Ovdje biraš kadar, model i postavke. Slike i rezultati ostaju u lokalnoj biblioteci.</p></div></li><li><span>02</span><div><strong>Jedan GPU po poslu</strong><p>Economy koristi jednu L4. Wan 2.2 bira jednu L40S ili A100. Bez paralelnih poslova iz aplikacije.</p></div></li><li><span>03</span><div><strong>Povratak rezultata</strong><p>MP4 se vraća u studio. Velika rezerva se nakon uspjeha zamjenjuje procjenom, a ukupni iznos usklađuješ s Modalom.</p></div></li></ol></section><div className="tip-card"><ShieldCheck size={21}/><div><strong>$15 za tehničke testove ostaje pravilo.</strong><p>Worker ima vremensko ograničenje i gasi se kada ne radi. Lokalna rezerva ne zamjenjuje limit na Modal računu.</p></div></div></div></div>}
    </>}
    <footer className="main-footer"><span>VideoGen · Klipanje</span><span>Oktobar 2026</span></footer>
   </main>
  </div>
  {notice&&<div className="toast" role="status"><Check size={16}/>{notice}<button onClick={()=>setNotice('')} aria-label="Zatvori obavijest"><X size={14}/></button></div>}
  {budgetReconcile&&<div className="modal-backdrop" onClick={()=>setBudgetReconcile(null)}><section className="panel modal-dialog" role="dialog" aria-modal="true" aria-labelledby="budget-invoice-title" onClick={e=>e.stopPropagation()}><button className="modal-close icon-button" aria-label="Zatvori" onClick={()=>setBudgetReconcile(null)}><X size={18}/></button><Wallet size={25}/><h2 id="budget-invoice-title">Uskladi ukupan iznos</h2><p>{budgetReconcile.id==='tests'?'Tehnički testovi':'Kreativne scene'}: unesi kumulativnu potrošnju ovog budžeta s Modala. Uključi i ranije usklađene iznose. Ako Modal koriguje obračun, možeš ispraviti i raniji veći zbir.</p><label>Ukupna potrošnja ovog budžeta (USD)<input autoFocus type="number" min="0" max="1000" step="0.01" value={budgetAmount} onChange={e=>setBudgetAmount(e.target.value)} placeholder="0.00"/></label><p className="field-hint">Sačekaj da Modal prikaže sve završene poslove. Ako račun koristiš i za druge projekte, unesi samo iznos pripisan ovom budžetu. Ovo mijenja lokalnu evidenciju i oslobađa stare rezervacije; ne prenosi novac.</p><button className="button primary" disabled={!budgetAmount||!Number.isFinite(Number(budgetAmount))||Number(budgetAmount)<0} onClick={reconcileBudget}>Sačuvaj ukupnu potrošnju</button></section></div>}
  {reconcile&&<div className="modal-backdrop" onClick={()=>setReconcile(null)}><section className="panel modal-dialog" role="dialog" aria-modal="true" aria-labelledby="invoice-title" onClick={e=>e.stopPropagation()}><button className="modal-close icon-button" aria-label="Zatvori" onClick={()=>setReconcile(null)}><X size={18}/></button><Wallet size={25}/><h2 id="invoice-title">Uskladi trošak pokušaja</h2><p>{reconcile.title}</p><label>Stvarni trošak s Modal računa (USD)<input autoFocus type="number" min="0" max="1000" step="0.0001" value={invoice} onChange={e=>setInvoice(e.target.value)} placeholder="0.0000"/></label><p className="field-hint">Unesi ukupan pripisani trošak resursa za ovaj pokušaj. Ovaj ručni unos oslobađa rezervaciju; aplikacija ne provjerava račun automatski.</p><button className="button primary" disabled={!invoice||!Number.isFinite(Number(invoice))||Number(invoice)<0} onClick={reconcileInvoice}>Sačuvaj uneseni trošak</button></section></div>}
 </div>
}

function EmptyState({icon,title,text,action,actionText}:{icon:ReactNode;title:string;text:string;action:()=>void;actionText:string}) {return <div className="empty-state"><span>{icon}</span><h2>{title}</h2><p>{text}</p><button className="button primary" onClick={action}>{actionText}<ArrowRight size={16}/></button></div>}
export default App
